import React from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import styled from 'styled-components';
import prog from './../media/Capa 3.svg';
import dib from './../media/Capa 4.svg';
const BigP = styled.span`
    font-size: 35px;
    @media only screen and (max-width: 900px)  {
        font-size: 20px;  
    }
    font-weight: bolder;
    color: ${props => props.color};
    margin:20px 10px;
    font-family: Monospace;
    letter-spacing: ${props => props.sp};
`

const Parent = styled.div`
position: relative;
width: max( 30vw , 300px ) ;
height: max(40vh , 100px ) ;
margin: 0px 50% ;
/* @media screen and (max-width:900px){
       display :none ;
} */
// 'height': '30vw'
`


const Simage = styled.img`
    position:absolute;
    top:0;
    left:0;
    width:100%;
    display:inline-block;
    animation-duration:5s;
    animation-delay: ${props => props.i};
    animation-timing-function: linear;
    animation-name: woosh;
    animation-iteration-count:infinite;
    opacity: 0;
  
  @keyframes woosh {
    0%,50%,100% {
      opacity: 0;
    }   
    10%,40%{ 
      opacity: 100;
    }
    
  }
  `

// Same box as the drawing (700x434); the dice's "cast the dice" bubble is placed here.
const DiceAnchor = styled.div`
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    aspect-ratio: 700 / 434;
    pointer-events: none;
    z-index: 1;
`

const InvRow = styled(Row)`
    display: flex;
    align-content: center;
    justify-content: center;
    @media only screen and (max-width: 900px) {
        flex-direction: column;
        align-items: center;
        justify-content: center;
  }

`



const Presentation = () => {
    return (

        <Container style={{ 'display': 'flex', 'justify-content': 'center', 'height': '90vh', 'margin':'auto' }}>
            <InvRow className='flex'>
                <Parent >
                <Simage i={"0s"} src={prog} />
                <Simage i={"2.5s"} src={dib}   />
                <DiceAnchor id="dice-prompt-anchor" />
                </Parent> 
                <Col style={{'display':'block', 'width': 'max(70vw' , 'justify-content':'center'  , 'align-items':'center'}}>
                    <BigP color="white" sp="4px" >Hi, I'm a</BigP>
                    <BigP color="khaki" sp="2px">Full-stack software developer,</BigP>
                    <BigP color="crimson" sp="2px" >Competitive programmer,</BigP>
                    <BigP color="midnightblue" sp="2px">Science and Art enthusiast.</BigP>
                    <BigP color="maroon" sp="2px">And I like to draw!✨ </BigP>
                </Col>
            </InvRow>
        </Container>
    );
}

export default Presentation;
